using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows.Forms;
using CreatorSettlement;
public static class TestsOpen {
 static int count;static string dir;static readonly BindingFlags FI=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Assert(bool ok,string text){if(!ok)throw new Exception("FAIL: "+text);count++;Console.WriteLine("PASS: "+text);}
 static IEnumerable<Control> Children(Control c){foreach(Control child in c.Controls){yield return child;foreach(var x in Children(child))yield return x;}}
 static object Field(object obj,string name){return obj.GetType().GetField(name,FI).GetValue(obj);}
 static void Shot(Form f,string name){Application.DoEvents();using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(0,0,f.Width,f.Height));b.Save(Path.Combine(dir,name));}}
 static void Prompt(Form owner,string[] paths,Action<SavedFilesWindow> choose,List<string> opened){using(var timer=new Timer{Interval=60}){timer.Tick+=(o,e)=>{var f=Application.OpenForms.OfType<SavedFilesWindow>().FirstOrDefault();if(f==null)return;timer.Stop();f.Opacity=0;choose(f);};timer.Start();SavedFilesPrompt.Show(owner,paths,p=>opened.Add(p));}}
 [STAThread] public static int Main(string[] args){try{dir=args[0];Directory.CreateDirectory(dir);Application.EnableVisualStyles();var paths=new[]{"结算核对.xlsx","打款信息.xlsx","异常报告.xlsx","结算调差.xlsx"}.Select(n=>Path.Combine(dir,n)).ToArray();var opened=new List<string>();
  using(var owner=new Form{Opacity=0,ShowInTaskbar=false}){owner.Show();Prompt(owner,new[]{paths[0]},f=>{Assert(f.SelectedFiles.SequenceEqual(new[]{paths[0]}),"single saved file selected by default");Shot(f,"ui-saved-single.png");Children(f).OfType<Button>().Single(b=>b.Text=="暂不打开").PerformClick();},opened);Assert(opened.Count==0,"later choice launches nothing");
   Prompt(owner,new[]{paths[0]},f=>{var b=Children(f).OfType<Button>().Single(x=>x.Text=="立即打开");Assert(b.Bottom<=b.Parent.ClientSize.Height,"open button fully visible");b.PerformClick();},opened);Assert(opened.SequenceEqual(new[]{paths[0]}),"open choice launches saved file");opened.Clear();
   Prompt(owner,paths,f=>{Assert(f.SelectedFiles.Length==4,"all four saved files checked");var list=Children(f).OfType<CheckedListBox>().Single();list.SetItemChecked(0,false);list.SetItemChecked(3,false);Shot(f,"ui-saved-all.png");Children(f).OfType<Button>().Single(b=>b.Text=="立即打开").PerformClick();},opened);Assert(opened.SequenceEqual(new[]{paths[1],paths[2]}),"only checked files launched");opened.Clear();
   Prompt(owner,paths,f=>{f.DialogResult=DialogResult.Cancel;f.Close();},opened);Assert(opened.Count==0,"closing prompt launches nothing");owner.Hide();}
  using(var f=new SavedFilesWindow(paths)){var list=Children(f).OfType<CheckedListBox>().Single();for(int i=0;i<4;i++)list.SetItemChecked(i,false);Assert(!Children(f).OfType<Button>().Single(b=>b.Text=="立即打开").Enabled,"no selection disables opening");list.SetItemChecked(1,true);Assert(Children(f).OfType<Button>().Single(b=>b.Text=="立即打开").Enabled,"checking re-enables opening");}
  var attempted=new List<string>();var errors=SavedFilesPrompt.OpenFiles(paths,p=>{attempted.Add(p);if(p==paths[0])throw new Exception("演示打开失败");});Assert(errors.Count==1&&attempted.Count==4,"one open failure does not stop remaining files");
  using(var f=new MainWindow()){f.Opacity=0;f.ShowInTaskbar=false;f.Show();var input=(Sheet)typeof(TestsV13).GetMethod("Input",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,null);typeof(MainWindow).GetField("sheets",FI).SetValue(f,new List<Sheet>{input});var choice=(ComboBox)Field(f,"sheetChoice");choice.Items.Add("演示明细");typeof(MainWindow).GetField("busy",FI).SetValue(f,true);choice.SelectedIndex=0;typeof(MainWindow).GetField("busy",FI).SetValue(f,false);typeof(MainWindow).GetMethod("LoadSelected",FI).Invoke(f,null);var model=(Model)Field(f,"model");model.Check.Rows[0][7]=22m;model.Refresh();model.SyncFixedToAdjustment();var store=(ReceiptStore)Field(f,"receiptStore");string id=store.Save(new Receipt{Channel="银行卡",Account="6222000000000001",Name="测试姓名",Phone="13800008000",Identity="110101199001010010"});store.Save(new Receipt{Channel="支付宝",Account="13800009000",Name="达人测试",Phone="13800009000",Identity="110101199001010010"});typeof(MainWindow).GetMethod("RefreshReceipts",FI).Invoke(f,new object[]{id});typeof(MainWindow).GetMethod("UseSelectedReceipt",FI).Invoke(f,null);
   for(int i=0;i<4;i++){typeof(MainWindow).GetMethod("Navigate",FI).Invoke(f,new object[]{i});Shot(f,new[]{"guide-check.png","guide-payment.png","guide-warning.png","guide-adjust.png"}[i]);}Assert(f.Text.EndsWith("v1.3.6"),"screenshots use updated version");typeof(MainWindow).GetMethod("Navigate",FI).Invoke(f,new object[]{0});using(var timer=new Timer{Interval=60}){timer.Tick+=(o,e)=>{var popup=Application.OpenForms.Cast<Form>().FirstOrDefault(x=>x.Text=="筛选：任务/方案ID");if(popup==null)return;timer.Stop();popup.Opacity=0;var values=Children(popup).OfType<CheckedListBox>().Single();for(int i=0;i<values.Items.Count;i++)values.SetItemChecked(i,values.Items[i].ToString()=="T1");Shot(popup,"guide-filter.png");Children(popup).OfType<Button>().Single(b=>b.Text=="应用").PerformClick();};timer.Start();typeof(GridFilter).GetMethod("Choose",FI).Invoke(Field(f,"checkFilter"),new object[]{"任务/方案ID"});}f.Hide();}
  using(var editor=new ReceiptEditor(new Receipt{Channel="银行卡",Account="6222000000000001",Name="测试姓名",Phone="13800008000",Identity="110101199001010010"})){editor.Opacity=0;editor.ShowInTaskbar=false;editor.Show();Shot(editor,"guide-receipt-editor.png");Children(editor).OfType<Button>().Single(b=>b.Text=="保存记录").PerformClick();Assert(editor.Result.Name=="测试姓名","receipt save button returns filled information");}
  Console.WriteLine("TOTAL "+count+" export and guide assertions passed");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
